            onPress={pickImage}
            disabled={uploading}
            className="flex-1 bg-neutral-900 rounded-2xl py-3.5 items-center"
          >
            {uploading
              ? <ActivityIndicator size="small" color="#fff" />
              : <Text className="text-white text-sm font-semibold">🖼️  Photo / Video</Text>
            }
          </TouchableOpacity>
