// ── Format helpers ──────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────

const FILE_SIZE_UNITS = ['B', 'KiB', 'MiB', 'GiB', 'TiB']

export const formatSize = (bytes: number): string => {
  if (bytes <= 0) return '0 B'
  const u = Math.min(Math.floor(Math.log2(bytes)) / 10, FILE_SIZE_UNITS.length - 1)
  return `${(bytes / (1 << (u * 10))).toFixed(2)} ${FILE_SIZE_UNITS[u]}`
}

export const getPublicUrl = (storedName: string): string =>
  `${BACKEND_URL}/storage/${encodeURIComponent(storedName)}`

