              <view className="mt-4">
                <text className="text-xs text-neutral-500">Uploading...</text>
              </view>
            )}
          </view>

          {error && (
            <view className="p-3 bg-red-50 border border-red-200 rounded-xl">
              <text className="text-sm text-red-600">{error}</text>
            </view>
          )}

